param([Parameter(Mandatory=$true)][string]$Path)
Add-Type -AssemblyName System.IO.Compression.FileSystem
$z=[IO.Compression.ZipFile]::OpenRead((Resolve-Path $Path));try{$e=$z.GetEntry('word/document.xml');$r=[IO.StreamReader]::new($e.Open());try{[xml]$x=$r.ReadToEnd()}finally{$r.Dispose()};$n=[Xml.XmlNamespaceManager]::new($x.NameTable);$n.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main');$body=$x.SelectSingleNode('//w:body',$n);$a=@($body.ChildNodes);$fig=@();$tab=@();for($i=0;$i-lt$a.Count;$i++){$q=$a[$i];if($q.LocalName-eq'p'){$t=(($q.SelectNodes('.//w:t',$n)|% InnerText)-join '');if($q.SelectNodes('.//w:drawing|.//w:pict',$n).Count){$next='';for($j=$i+1;$j-lt$a.Count;$j++){if($a[$j].LocalName-eq'p'){$next=(($a[$j].SelectNodes('.//w:t',$n)|% InnerText)-join '');if($next){break}}};$fig+=$next}}elseif($q.LocalName-eq'tbl'){$prev='';for($j=$i-1;$j-ge0;$j--){if($a[$j].LocalName-eq'p'){$prev=(($a[$j].SelectNodes('.//w:t',$n)|% InnerText)-join '');if($prev){break}}};$tab+=$prev}};[pscustomobject]@{FigureCaptions=$fig;TableCaptions=$tab}}finally{$z.Dispose()}
